import aiofiles.os

async def prepare(path):
    await aiofiles.os.makedirs('/data/out', exist_ok=True)
    if await aiofiles.os.path.exists(path):
        info = await aiofiles.os.stat(path)
        if info.st_size == 0:
            await aiofiles.os.remove(path)
    return await aiofiles.os.listdir('/data/out')

class ApiClient:
    def __init__(self) -> None:
        self._session: aiohttp.ClientSession | None = None

    async def start(self) -> None:
        self._session = aiohttp.ClientSession()

    async def close(self) -> None:
        if self._session:
            await self._session.close()

from aiohttp import web

@web.middleware
async def error_mw(request, handler):
    try:
        return await handler(request)
    except web.HTTPException:
        raise
    except Exception:
        return web.json_response({'error': 'internal'}, status=500)

app = web.Application(middlewares=[error_mw])

from aiohttp_retry import RetryOptionsBase

class CappedRetry(RetryOptionsBase):
    def get_timeout(self, attempt: int, response=None) -> float:
        return min(2 ** attempt, 30)

