async function login(email, password) {
  const user = await db.users.findByEmail(email);
  if (!user) return null;
  if (!(await bcrypt.compare(password, user.passwordHash))) return null;

  if (bcrypt.getRounds(user.passwordHash) < TARGET_ROUNDS) {
