function luminance(input) {
  const [r, g, b] = parseSafeColor(input).map((v, i) => i < 3 ? v / 255 : v);
  const linear = [r, g, b].map((c) =>
    c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4
  );
  return 0.2126 * linear[0] + 0.7152 * linear[1] + 0.0722 * linear[2];
}

