@cython.cfunc
@cython.exceptval(-1, check=False)
def _clamp(x: cython.int, lo: cython.int, hi: cython.int) -> cython.int:
    if x < lo:
        return lo
    return hi if x > hi else x

def clamp_all(values: list) -> list:
    i: cython.Py_ssize_t
