function assertAcyclic(value, seen = new WeakSet()) {
  if (!value || typeof value !== 'object') return;
  if (seen.has(value)) throw new TypeError('Circular value');
  seen.add(value);
  for (const child of Object.values(value)) assertAcyclic(child, seen);
  seen.delete(value);
}

