  const tech = m.isVariable ? ' tech(variations)' : '';
  return `@font-face {
  font-family: ${JSON.stringify(m.family)};
  font-style: ${m.style};
  font-weight: ${m.weight};
  font-display: swap;
  unicode-range: ${m.unicodeRange};
  src: url(${JSON.stringify(url)}) format('${m.format}')${tech};
}`;
}

