from giturlparse import parse

def repository_key(url: str) -> tuple[str, str, str]:
    remote = parse(url)
    if not remote.valid:
        raise ValueError('unsupported Git URL')
    return remote.host.lower(), remote.owner.lower(), remote.repo.removesuffix('.git').lower()

