function compositeOnWhite(rgba) {
  const rgb = new Uint8Array((rgba.length / 4) * 3);
  for (let s = 0, d = 0; s < rgba.length; s += 4) {
    const a = rgba[s + 3] / 255;
    rgb[d++] = rgba[s] * a + 255 * (1 - a);
    rgb[d++] = rgba[s + 1] * a + 255 * (1 - a);
    rgb[d++] = rgba[s + 2] * a + 255 * (1 - a);
  }
  return rgb;
}

