import numpy as np
from numba import njit

@njit
def pairwise_min_dist(xs, ys):
    best = np.inf
    for i in range(xs.shape[0]):
        for j in range(ys.shape[0]):
            d = (xs[i] - ys[j]) ** 2
            if d < best:
                best = d
    return np.sqrt(best)

pairwise_min_dist(a, b)  # first call compiles
pairwise_min_dist(a, b)  # this is the one worth timing

