from numba import njit, prange, set_num_threads, get_num_threads

@njit(parallel=True)
def row_norms(m):
    out = np.empty(m.shape[0])
    for i in prange(m.shape[0]):
        acc = 0.0
        for j in range(m.shape[1]):
            acc += m[i, j] ** 2
        out[i] = np.sqrt(acc)
    return out

