import psutil

def kill_tree(pid, timeout=3):
    parent = psutil.Process(pid)
    procs = parent.children(recursive=True) + [parent]
    for p in procs:
        p.terminate()
    gone, alive = psutil.wait_procs(procs, timeout=timeout)
    for p in alive:
        p.kill()

