declare module 'react-clientside-effect' {
  import type { ComponentType } from 'react';
  export default function withClientSideEffect<P, S>(
    reduce: (props: P[]) => S,
    apply: (state: S) => void
  ): (component: ComponentType<P>) => ComponentType<P> & { peek(): S };
}

