function Tabs({ activeId, tabs }) {
  return tabs.map((tab) => (
    <Freeze key={tab.id} freeze={tab.id !== activeId}>
      <div role="tabpanel" aria-label={tab.label}>
        <tab.Component />
      </div>
    </Freeze>
  ));
}

function StackScreen({ depthFromTop, children }) {
