  activeSticky.current =
    [...stickyIndexes].reverse().find((i) => range.startIndex >= i) ?? 0
  const next = new Set([activeSticky.current, ...defaultRangeExtractor(range)])
  return [...next].sort((a, b) => a - b)
}, [])

