const { Parser } = require('xml2js')

async function parseAll(files) {
  const out = []
  for (const file of files) {
    const parser = new Parser({ explicitArray: false })
    out.push(await parser.parseStringPromise(await fs.readFile(file)))
  }
  return out
}

